/**
 * tests/adversarial-prod1-service.js
 * 
 * Adversarial Stress Verification Suite for CineJoy On-Device JS Service
 * Target Component: services/com.cinejoy.tv.service/
 * Service ID: com.cinejoy.tv.service
 * Target Platform: LG webOS 8.5.0 (Node.js 12.22.2 standard, Linux aarch64)
 * 
 * Stress Dimensions:
 * 1. Port collision resilience: port fallback when 8088 (and multiple ports) are occupied.
 * 2. HTTP 206 Partial Content range requests and client abort socket cleanup.
 * 3. Concurrency and rapid request stress.
 * 4. Manifest rewriting edge cases.
 * 
 * RUNTIME COMPATIBILITY:
 * - Pure Node.js built-ins (http, https, net, fs, path, crypto, stream, url, child_process).
 * - Zero external npm dependencies.
 * - Compatible with Node 12.22.2 through modern Node.
 */

'use strict';

const http = require('http');
const https = require('https');
const net = require('net');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { spawn } = require('child_process');
const { URL } = require('url');

const SERVICE_DIR = path.resolve(__dirname, '../services/com.cinejoy.tv.service');
const SERVICE_INDEX = path.join(SERVICE_DIR, 'index.js');
const STATUS_FILE = path.join(SERVICE_DIR, '.server-port');
const STATUS_JSON_FILE = path.join(SERVICE_DIR, '.status.json');

const hlsProxy = require(path.join(SERVICE_DIR, 'hls-proxy.js'));
const resolver = require(path.join(SERVICE_DIR, 'resolver.js'));

// ANSI Colors
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m',
  gray: '\x1b[90m',
  magenta: '\x1b[35m'
};

let testCount = 0;
let passCount = 0;
let failCount = 0;
const testResults = [];

function recordResult(id, title, passed, durationMs, details, error) {
  testCount++;
  if (passed) {
    passCount++;
    console.log('  [' + id + '] ' + title + ' ... ' + C.green + '✔ PASS' + C.reset + ' ' + C.gray + '(' + durationMs + 'ms)' + C.reset);
  } else {
    failCount++;
    console.log('  [' + id + '] ' + title + ' ... ' + C.red + '✖ FAIL' + C.reset + ' ' + C.gray + '(' + durationMs + 'ms)' + C.reset);
    if (error) {
      console.log('      ' + C.red + 'Error: ' + (error.stack || error.message || error) + C.reset);
    }
  }
  if (details && (process.env.VERBOSE || !passed)) {
    console.log('      ' + C.gray + 'Details: ' + JSON.stringify(details) + C.reset);
  }
  testResults.push({ id: id, title: title, passed: passed, durationMs: durationMs, details: details, error: error ? error.message : null });
}

async function runTest(id, title, testFn) {
  const start = Date.now();
  try {
    const details = await testFn();
    const duration = Date.now() - start;
    recordResult(id, title, true, duration, details);
  } catch (err) {
    const duration = Date.now() - start;
    recordResult(id, title, false, duration, null, err);
  }
}

/**
 * Ensures a port is completely free on 127.0.0.1
 */
function ensurePortFree(port, maxWaitMs) {
  maxWaitMs = maxWaitMs || 3000;
  const start = Date.now();
  return new Promise(function (resolve) {
    function check() {
      const tester = net.createServer();
      tester.once('error', function (err) {
        if (Date.now() - start >= maxWaitMs) {
          resolve(false);
        } else {
          setTimeout(check, 100);
        }
      });
      tester.once('listening', function () {
        tester.close(function () {
          resolve(true);
        });
      });
      tester.listen(port, '127.0.0.1');
    }
    check();
  });
}

/**
 * HTTP Request helper returning full response object
 */
function httpRequest(options, body) {
  return new Promise(function (resolve, reject) {
    const isHttps = options.protocol === 'https:';
    const client = isHttps ? https : http;
    const reqOpts = Object.assign({}, options);
    reqOpts.headers = Object.assign({}, options.headers || {});

    if (body && !reqOpts.headers['Content-Length'] && !reqOpts.headers['content-length']) {
      reqOpts.headers['Content-Length'] = Buffer.isBuffer(body) ? body.length : Buffer.byteLength(body);
    }

    const req = client.request(reqOpts, function (res) {
      const chunks = [];
      res.on('data', function (c) { chunks.push(c); });
      res.on('end', function () {
        const buf = Buffer.concat(chunks);
        let text = null;
        let json = null;
        try {
          text = buf.toString('utf8');
          json = JSON.parse(text);
        } catch (_) {}
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          buffer: buf,
          text: text,
          json: json
        });
      });
    });

    req.on('error', reject);

    const timeoutMs = options.timeout || 10000;
    req.setTimeout(timeoutMs, function () {
      req.abort();
      reject(new Error('HTTP request timed out after ' + timeoutMs + 'ms'));
    });

    if (body) req.write(body);
    req.end();
  });
}

/**
 * Creates a dummy TCP server occupying a specific port
 */
function createDummyPortHolder(port, host) {
  host = host || '127.0.0.1';
  return new Promise(function (resolve, reject) {
    const server = http.createServer(function (req, res) {
      res.writeHead(200, { 'Content-Type': 'text/plain' });
      res.end('OCCUPIED_PORT_' + port);
    });
    server.on('error', reject);
    server.listen(port, host, function () {
      resolve({
        port: port,
        close: function () {
          return new Promise(function (resClose) {
            server.close(function () {
              setTimeout(resClose, 50);
            });
          });
        }
      });
    });
  });
}

/**
 * Polls until HTTP server responds on target port
 */
async function waitForPortReady(port, maxWaitMs) {
  maxWaitMs = maxWaitMs || 5000;
  const start = Date.now();
  while (Date.now() - start < maxWaitMs) {
    try {
      const res = await httpRequest({
        hostname: '127.0.0.1',
        port: port,
        path: '/health',
        method: 'GET',
        timeout: 400
      });
      if (res.statusCode === 200 && res.json && res.json.status === 'ok') {
        return true;
      }
    } catch (_) {}
    await new Promise(function (r) { setTimeout(r, 80); });
  }
  return false;
}

/**
 * Spawns service as child process
 */
function spawnServiceProcess(envOverrides) {
  const env = Object.assign({}, process.env, envOverrides || {});
  const child = spawn(process.execPath, [SERVICE_INDEX], {
    cwd: SERVICE_DIR,
    env: env,
    stdio: ['ignore', 'pipe', 'pipe']
  });

  let stdout = '';
  let stderr = '';
  child.stdout.on('data', function (d) { stdout += d.toString(); });
  child.stderr.on('data', function (d) { stderr += d.toString(); });

  return {
    process: child,
    getStdout: function () { return stdout; },
    getStderr: function () { return stderr; },
    kill: function () {
      return new Promise(function (resolve) {
        if (child.killed || child.exitCode !== null) return resolve();
        child.on('exit', function () {
          setTimeout(resolve, 80);
        });
        child.kill('SIGTERM');
        setTimeout(function () {
          try { child.kill('SIGKILL'); } catch (_) {}
          resolve();
        }, 1500);
      });
    }
  };
}

// =============================================================================
// MAIN TEST RUNNER
// =============================================================================
async function runAllSuites() {
  console.log('\n' + C.bold + '================================================================' + C.reset);
  console.log(C.bold + '   CINEJOY ADVERSARIAL STRESS TEST SUITE: com.cinejoy.tv.service' + C.reset);
  console.log(C.bold + '================================================================' + C.reset);
  console.log('► Target: ' + SERVICE_DIR);
  console.log('► Node.js: ' + process.version + ' (' + process.platform + ' ' + process.arch + ')');
  console.log('► Starting Adversarial Stress Verifications...\n');

  // ===========================================================================
  // SUITE 1: Port Collision Resilience
  // ===========================================================================
  console.log(C.bold + '► SUITE 1: Port Collision Resilience' + C.reset);

  await runTest('T1.1', 'Baseline port binding (127.0.0.1:8088)', async function () {
    const isFree = await ensurePortFree(8088, 3000);
    if (!isFree) throw new Error('Port 8088 is occupied by external process before test start');

    const serviceChild = spawnServiceProcess({ PORT: '8088' });
    try {
      const ready = await waitForPortReady(8088, 5000);
      if (!ready) throw new Error('Service did not become ready on 8088 within 5s\nStdout: ' + serviceChild.getStdout() + '\nStderr: ' + serviceChild.getStderr());

      const res = await httpRequest({ hostname: '127.0.0.1', port: 8088, path: '/health', method: 'GET' });
      if (res.statusCode !== 200) throw new Error('Expected 200, got ' + res.statusCode);
      if (res.json.port !== 8088) throw new Error('Expected port 8088 in health response, got ' + res.json.port);

      if (!fs.existsSync(STATUS_FILE)) throw new Error('.server-port file missing');
      const recordedPort = parseInt(fs.readFileSync(STATUS_FILE, 'utf8'), 10);
      if (recordedPort !== 8088) throw new Error('Expected 8088 in .server-port, got ' + recordedPort);

      return { port: recordedPort, mode: res.json.mode };
    } finally {
      await serviceChild.kill();
      await ensurePortFree(8088, 2000);
    }
  });

  await runTest('T1.2', 'Single port collision: fallback to 8089 when 8088 is occupied', async function () {
    await ensurePortFree(8088, 2000);
    await ensurePortFree(8089, 2000);
    const dummy8088 = await createDummyPortHolder(8088, '127.0.0.1');
    const serviceChild = spawnServiceProcess({ PORT: '8088' });
    try {
      const ready = await waitForPortReady(8089, 5000);
      if (!ready) throw new Error('Service failed to fallback and bind to 8089\nStdout: ' + serviceChild.getStdout());

      // Verify health on 8089
      const res = await httpRequest({ hostname: '127.0.0.1', port: 8089, path: '/health', method: 'GET' });
      if (res.statusCode !== 200) throw new Error('Health on 8089 returned ' + res.statusCode);
      if (res.json.port !== 8089) throw new Error('Expected port: 8089, got ' + res.json.port);

      // Verify status files reflect port 8089
      const recordedPort = parseInt(fs.readFileSync(STATUS_FILE, 'utf8'), 10);
      if (recordedPort !== 8089) throw new Error('Expected .server-port to contain 8089, got ' + recordedPort);

      const statusJson = JSON.parse(fs.readFileSync(STATUS_JSON_FILE, 'utf8'));
      if (statusJson.port !== 8089) throw new Error('Expected .status.json port: 8089, got ' + statusJson.port);

      // Verify dummy server on 8088 was not disrupted
      const dummyRes = await httpRequest({ hostname: '127.0.0.1', port: 8088, path: '/', method: 'GET' });
      if (dummyRes.text !== 'OCCUPIED_PORT_8088') throw new Error('Dummy server response altered: ' + dummyRes.text);

      return { fallbackPort: 8089, dummyIntact: true };
    } finally {
      await serviceChild.kill();
      await dummy8088.close();
      await ensurePortFree(8088, 2000);
      await ensurePortFree(8089, 2000);
    }
  });

  await runTest('T1.3', 'Multi-port cascading collision (8088..8091 occupied -> fallback 8092)', async function () {
    for (let p = 8088; p <= 8092; p++) {
      await ensurePortFree(p, 2000);
    }
    const dummies = [];
    dummies.push(await createDummyPortHolder(8088, '127.0.0.1'));
    dummies.push(await createDummyPortHolder(8089, '127.0.0.1'));
    dummies.push(await createDummyPortHolder(8090, '127.0.0.1'));
    dummies.push(await createDummyPortHolder(8091, '127.0.0.1'));

    const serviceChild = spawnServiceProcess({ PORT: '8088' });
    try {
      const ready = await waitForPortReady(8092, 6000);
      if (!ready) throw new Error('Service failed to cascade to 8092\nStdout: ' + serviceChild.getStdout());

      const res = await httpRequest({ hostname: '127.0.0.1', port: 8092, path: '/health', method: 'GET' });
      if (res.statusCode !== 200 || res.json.port !== 8092) {
        throw new Error('Expected health on 8092 with port 8092, got: ' + JSON.stringify(res.json));
      }

      const recordedPort = parseInt(fs.readFileSync(STATUS_FILE, 'utf8'), 10);
      if (recordedPort !== 8092) throw new Error('Expected 8092 in .server-port, got ' + recordedPort);

      return { cascadedPort: 8092, attemptsLogged: serviceChild.getStdout().includes('Port 8091 in use') };
    } finally {
      await serviceChild.kill();
      for (let i = 0; i < dummies.length; i++) {
        await dummies[i].close();
      }
      for (let p = 8088; p <= 8092; p++) {
        await ensurePortFree(p, 2000);
      }
    }
  });

  await runTest('T1.4', 'Port collision with wildcard 0.0.0.0:8088 listener', async function () {
    await ensurePortFree(8088, 2000);
    await ensurePortFree(8089, 2000);
    const dummyWildcard = await createDummyPortHolder(8088, '0.0.0.0');
    const serviceChild = spawnServiceProcess({ PORT: '8088' });
    try {
      const ready = await waitForPortReady(8089, 5000);
      if (!ready) throw new Error('Service failed to bind to 8089 when 0.0.0.0:8088 is occupied');

      const res = await httpRequest({ hostname: '127.0.0.1', port: 8089, path: '/health', method: 'GET' });
      if (res.json.port !== 8089) throw new Error('Expected port 8089, got ' + res.json.port);

      return { fallbackPort: 8089 };
    } finally {
      await serviceChild.kill();
      await dummyWildcard.close();
      await ensurePortFree(8088, 2000);
      await ensurePortFree(8089, 2000);
    }
  });

  await runTest('T1.5', 'Port exhaustion limit: reject and exit when all 10 ports (8088-8097) occupied', async function () {
    for (let p = 8088; p <= 8097; p++) {
      await ensurePortFree(p, 2000);
    }
    const dummies = [];
    for (let p = 8088; p <= 8097; p++) {
      dummies.push(await createDummyPortHolder(p, '127.0.0.1'));
    }

    const serviceChild = spawnServiceProcess({ PORT: '8088' });
    try {
      // Service should terminate with non-zero exit code because all 10 attempts fail
      const exitPromise = new Promise(function (resolve) {
        serviceChild.process.on('exit', function (code) { resolve(code); });
      });

      const exitCode = await Promise.race([
        exitPromise,
        new Promise(function (_, reject) { setTimeout(function () { reject(new Error('Process did not exit on exhaustion timeout')); }, 4000); })
      ]);

      if (exitCode !== 1) throw new Error('Expected exit code 1 on port exhaustion, got ' + exitCode);
      const stderr = serviceChild.getStderr();
      if (!stderr.includes('Could not bind to any port in range 8088-8097')) {
        throw new Error('Expected exhaustion error message in stderr, got: ' + stderr);
      }

      return { exitCode: exitCode, messageMatched: true };
    } finally {
      await serviceChild.kill();
      for (let i = 0; i < dummies.length; i++) {
        await dummies[i].close();
      }
      for (let p = 8088; p <= 8097; p++) {
        await ensurePortFree(p, 2000);
      }
    }
  });

  await runTest('T1.6', 'Clean shutdown & status file removal on fallback port', async function () {
    await ensurePortFree(8088, 2000);
    await ensurePortFree(8089, 2000);
    const dummy8088 = await createDummyPortHolder(8088, '127.0.0.1');
    const serviceChild = spawnServiceProcess({ PORT: '8088' });
    try {
      await waitForPortReady(8089, 5000);
      if (!fs.existsSync(STATUS_FILE)) throw new Error('.server-port was not created');

      await serviceChild.kill();

      if (fs.existsSync(STATUS_FILE)) throw new Error('.server-port still exists after shutdown');
      if (fs.existsSync(STATUS_JSON_FILE)) throw new Error('.status.json still exists after shutdown');

      // Verify port 8089 is immediately free for new listener
      const isFree = await ensurePortFree(8089, 2000);
      if (!isFree) throw new Error('Port 8089 was not released after shutdown');

      return { statusFilesCleaned: true, portReleased: true };
    } finally {
      await dummy8088.close();
      await ensurePortFree(8088, 2000);
      await ensurePortFree(8089, 2000);
    }
  });

  // ===========================================================================
  // SUITE 2: HTTP 206 Partial Content Range Requests & Client Abort Socket Cleanup
  // ===========================================================================
  console.log('\n' + C.bold + '► SUITE 2: HTTP 206 Partial Content & Client Abort Cleanup' + C.reset);

  // Set up mock upstream server for precise range and abort testing
  const mockMediaData = crypto.randomBytes(1024 * 1024 * 4); // 4 MB pseudo-video
  let mockServerPort = 0;
  let mockActiveConnections = 0;
  let lastMockUpstreamAborted = false;

  const mockUpstreamServer = http.createServer(function (req, res) {
    mockActiveConnections++;
    const parsed = new URL(req.url, 'http://127.0.0.1:' + mockServerPort);

    // Delayed redirect mock endpoint
    if (parsed.pathname === '/redirect-delayed') {
      setTimeout(function () {
        if (!res.writableEnded) {
          res.writeHead(302, { Location: 'http://127.0.0.1:' + mockServerPort + '/media.mp4' });
          res.end();
        }
      }, 200);
      return;
    }

    if (parsed.pathname === '/media.mp4') {
      const range = req.headers.range;
      const totalLen = mockMediaData.length;

      // Track upstream abort
      req.on('close', function () {
        mockActiveConnections--;
        if (!res.writableEnded) {
          lastMockUpstreamAborted = true;
        }
      });

      if (!range) {
        res.writeHead(200, {
          'Content-Type': 'video/mp4',
          'Content-Length': totalLen,
          'Accept-Ranges': 'bytes'
        });
        if (req.method === 'HEAD') return res.end();
        return res.end(mockMediaData);
      }

      // Parse range: bytes=start-end
      const match = /^bytes=(\d*)-(\d*)$/.exec(range);
      if (!match) {
        res.writeHead(416, { 'Content-Range': 'bytes */' + totalLen });
        return res.end();
      }

      let start = match[1] ? parseInt(match[1], 10) : undefined;
      let end = match[2] ? parseInt(match[2], 10) : undefined;

      if (start === undefined && end !== undefined) {
        // Suffix range: bytes=-500
        start = totalLen - end;
        end = totalLen - 1;
      } else if (start !== undefined && end === undefined) {
        // Open-ended range: bytes=1000-
        end = totalLen - 1;
      }

      if (start > end || start >= totalLen) {
        res.writeHead(416, { 'Content-Range': 'bytes */' + totalLen });
        return res.end();
      }

      end = Math.min(end, totalLen - 1);
      const chunkLen = end - start + 1;
      const slice = mockMediaData.slice(start, end + 1);

      res.writeHead(206, {
        'Content-Type': 'video/mp4',
        'Content-Range': 'bytes ' + start + '-' + end + '/' + totalLen,
        'Content-Length': chunkLen,
        'Accept-Ranges': 'bytes'
      });

      if (req.method === 'HEAD') return res.end();

      // Stream slice with small chunks to allow abort interception
      const CHUNK_SIZE = 64 * 1024;
      let offset = 0;
      function pushChunk() {
        if (offset >= slice.length || res.writableEnded) {
          if (!res.writableEnded) res.end();
          return;
        }
        const next = slice.slice(offset, offset + CHUNK_SIZE);
        offset += next.length;
        const canContinue = res.write(next);
        if (canContinue) {
          setTimeout(pushChunk, 10);
        } else {
          res.once('drain', pushChunk);
        }
      }
      pushChunk();
      return;
    }

    res.writeHead(404);
    res.end();
  });

  await new Promise(function (resolve) {
    mockUpstreamServer.listen(0, '127.0.0.1', function () {
      mockServerPort = mockUpstreamServer.address().port;
      resolve();
    });
  });

  // Start service on dedicated test port
  await ensurePortFree(8188, 2000);
  const service2 = spawnServiceProcess({ PORT: '8188' });
  await waitForPortReady(8188, 5000);

  try {
    await runTest('T2.1', 'Standard initial Range request (bytes=0-1023 -> HTTP 206)', async function () {
      const targetUrl = 'http://127.0.0.1:' + mockServerPort + '/media.mp4';
      const proxyUrl = '/hls/proxy?url=' + encodeURIComponent(targetUrl);

      const res = await httpRequest({
        hostname: '127.0.0.1',
        port: 8188,
        path: proxyUrl,
        method: 'GET',
        headers: { Range: 'bytes=0-1023' }
      });

      if (res.statusCode !== 206) throw new Error('Expected HTTP 206, got ' + res.statusCode);
      if (res.headers['content-range'] !== 'bytes 0-1023/' + mockMediaData.length) {
        throw new Error('Unexpected Content-Range: ' + res.headers['content-range']);
      }
      if (parseInt(res.headers['content-length'], 10) !== 1024) {
        throw new Error('Unexpected Content-Length: ' + res.headers['content-length']);
      }
      if (res.buffer.length !== 1024) throw new Error('Expected 1024 bytes buffer, got ' + res.buffer.length);

      const expectedSlice = mockMediaData.slice(0, 1024);
      if (!res.buffer.equals(expectedSlice)) throw new Error('Buffer content does not match mockMediaData slice');

      return { status: 206, bytesReceived: res.buffer.length, rangeHeader: res.headers['content-range'] };
    });

    await runTest('T2.2', 'Middle Range request (bytes=100000-199999 -> HTTP 206)', async function () {
      const targetUrl = 'http://127.0.0.1:' + mockServerPort + '/media.mp4';
      const proxyUrl = '/hls/proxy?url=' + encodeURIComponent(targetUrl);

      const res = await httpRequest({
        hostname: '127.0.0.1',
        port: 8188,
        path: proxyUrl,
        method: 'GET',
        headers: { Range: 'bytes=100000-199999' }
      });

      if (res.statusCode !== 206) throw new Error('Expected HTTP 206, got ' + res.statusCode);
      if (res.headers['content-range'] !== 'bytes 100000-199999/' + mockMediaData.length) {
        throw new Error('Unexpected Content-Range: ' + res.headers['content-range']);
      }
      const expectedSlice = mockMediaData.slice(100000, 200000);
      if (!res.buffer.equals(expectedSlice)) throw new Error('Middle slice content mismatch');

      return { status: 206, bytesReceived: res.buffer.length };
    });

    await runTest('T2.3', 'Suffix Range request (bytes=-2048 -> last 2048 bytes)', async function () {
      const targetUrl = 'http://127.0.0.1:' + mockServerPort + '/media.mp4';
      const proxyUrl = '/hls/proxy?url=' + encodeURIComponent(targetUrl);

      const res = await httpRequest({
        hostname: '127.0.0.1',
        port: 8188,
        path: proxyUrl,
        method: 'GET',
        headers: { Range: 'bytes=-2048' }
      });

      if (res.statusCode !== 206) throw new Error('Expected HTTP 206, got ' + res.statusCode);
      const totalLen = mockMediaData.length;
      const expectedRange = 'bytes ' + (totalLen - 2048) + '-' + (totalLen - 1) + '/' + totalLen;
      if (res.headers['content-range'] !== expectedRange) {
        throw new Error('Expected Content-Range: ' + expectedRange + ', got ' + res.headers['content-range']);
      }
      const expectedSlice = mockMediaData.slice(totalLen - 2048);
      if (!res.buffer.equals(expectedSlice)) throw new Error('Suffix buffer mismatch');

      return { status: 206, range: res.headers['content-range'] };
    });

    await runTest('T2.4', 'Open-ended Range request (bytes=3000000- -> EOF)', async function () {
      const targetUrl = 'http://127.0.0.1:' + mockServerPort + '/media.mp4';
      const proxyUrl = '/hls/proxy?url=' + encodeURIComponent(targetUrl);

      const res = await httpRequest({
        hostname: '127.0.0.1',
        port: 8188,
        path: proxyUrl,
        method: 'GET',
        headers: { Range: 'bytes=3000000-' }
      });

      if (res.statusCode !== 206) throw new Error('Expected HTTP 206, got ' + res.statusCode);
      const totalLen = mockMediaData.length;
      const expectedLen = totalLen - 3000000;
      if (res.buffer.length !== expectedLen) throw new Error('Expected ' + expectedLen + ' bytes, got ' + res.buffer.length);

      return { status: 206, bytesReceived: res.buffer.length };
    });

    await runTest('T2.5', 'HEAD request with Range header', async function () {
      const targetUrl = 'http://127.0.0.1:' + mockServerPort + '/media.mp4';
      const proxyUrl = '/hls/proxy?url=' + encodeURIComponent(targetUrl);

      const res = await httpRequest({
        hostname: '127.0.0.1',
        port: 8188,
        path: proxyUrl,
        method: 'HEAD',
        headers: { Range: 'bytes=0-1023' }
      });

      if (res.statusCode !== 206) throw new Error('Expected 206 on HEAD with range, got ' + res.statusCode);
      if (res.buffer.length !== 0) throw new Error('HEAD response returned non-zero body length: ' + res.buffer.length);
      if (res.headers['content-range'] !== 'bytes 0-1023/' + mockMediaData.length) {
        throw new Error('Unexpected Content-Range header: ' + res.headers['content-range']);
      }

      return { status: 206, bodyLength: 0 };
    });

    await runTest('T2.6', 'Unsatisfiable range upstream error (bytes=99999999-99999999 -> HTTP 416)', async function () {
      const targetUrl = 'http://127.0.0.1:' + mockServerPort + '/media.mp4';
      const proxyUrl = '/hls/proxy?url=' + encodeURIComponent(targetUrl);

      const res = await httpRequest({
        hostname: '127.0.0.1',
        port: 8188,
        path: proxyUrl,
        method: 'GET',
        headers: { Range: 'bytes=99999999-99999999' }
      });

      if (res.statusCode !== 416) throw new Error('Expected 416, got ' + res.statusCode);
      if (!res.headers['access-control-allow-origin']) throw new Error('Missing CORS header on error response');

      return { status: 416, corsPresent: true };
    });

    await runTest('T2.7', 'Client abort during stream transfer: upstream destruction and zero leaks', async function () {
      const targetUrl = 'http://127.0.0.1:' + mockServerPort + '/media.mp4';
      const proxyUrl = '/hls/proxy?url=' + encodeURIComponent(targetUrl);

      // Baseline health & RSS
      const startHealth = await httpRequest({ hostname: '127.0.0.1', port: 8188, path: '/health', method: 'GET' });
      const startRssMB = startHealth.json.memory.rss / (1024 * 1024);

      lastMockUpstreamAborted = false;

      // Repeat abort 15 times to verify RSS stability and absence of uncaught crash
      for (let i = 0; i < 15; i++) {
        await new Promise(function (resolve) {
          const req = http.request({
            hostname: '127.0.0.1',
            port: 8188,
            path: proxyUrl,
            method: 'GET'
          }, function (res) {
            let received = 0;
            res.on('data', function (c) {
              received += c.length;
              if (received >= 64 * 1024) {
                // Abruptly destroy client socket mid-stream
                req.socket.destroy();
                resolve();
              }
            });
          });
          req.on('error', function () { resolve(); });
          req.end();
        });
      }

      // Allow 200ms for event loop cleanup
      await new Promise(function (r) { setTimeout(r, 200); });

      // Service should still be alive and healthy
      const healthRes = await httpRequest({ hostname: '127.0.0.1', port: 8188, path: '/health', method: 'GET' });
      if (healthRes.statusCode !== 200) throw new Error('Service crashed or unresponsive after aborts');

      const endRssMB = healthRes.json.memory.rss / (1024 * 1024);
      const rssDriftMB = endRssMB - startRssMB;

      // Drift from 15 aborts should be under 15 MB
      if (rssDriftMB > 15) {
        throw new Error('Excessive RSS drift after aborts: ' + rssDriftMB.toFixed(2) + ' MB (start: ' + startRssMB.toFixed(1) + ', end: ' + endRssMB.toFixed(1) + ')');
      }

      return { abortIterations: 15, serviceHealthy: true, startRssMB: startRssMB.toFixed(1), endRssMB: endRssMB.toFixed(1), driftMB: rssDriftMB.toFixed(2) };
    });

    await runTest('T2.8', 'Client abort during upstream redirect delay', async function () {
      const targetUrl = 'http://127.0.0.1:' + mockServerPort + '/redirect-delayed';
      const proxyUrl = '/hls/proxy?url=' + encodeURIComponent(targetUrl);

      await new Promise(function (resolve) {
        const req = http.request({
          hostname: '127.0.0.1',
          port: 8188,
          path: proxyUrl,
          method: 'GET'
        });
        req.on('error', function () { resolve(); });
        // Abort after 50ms while upstream redirect is pending
        setTimeout(function () {
          req.socket.destroy();
          resolve();
        }, 50);
        req.end();
      });

      await new Promise(function (r) { setTimeout(r, 300); });

      const healthRes = await httpRequest({ hostname: '127.0.0.1', port: 8188, path: '/health', method: 'GET' });
      if (healthRes.statusCode !== 200) throw new Error('Service failed after redirect abort');

      return { redirectedAbortHandled: true };
    });

  } finally {
    await service2.kill();
    await new Promise(function (r) { mockUpstreamServer.close(r); });
    await ensurePortFree(8188, 2000);
  }

  // ===========================================================================
  // SUITE 3: Concurrency and Rapid Request Stress
  // ===========================================================================
  console.log('\n' + C.bold + '► SUITE 3: Concurrency and Rapid Request Stress' + C.reset);

  await ensurePortFree(8288, 2000);
  const service3 = spawnServiceProcess({ PORT: '8288' });
  await waitForPortReady(8288, 5000);

  try {
    await runTest('T3.1', 'Burst concurrency on /health (100 parallel requests)', async function () {
      const promises = [];
      const start = Date.now();
      for (let i = 0; i < 100; i++) {
        promises.push(httpRequest({ hostname: '127.0.0.1', port: 8288, path: '/health', method: 'GET', timeout: 5000 }));
      }
      const results = await Promise.all(promises);
      const duration = Date.now() - start;

      let okCount = 0;
      for (let j = 0; j < results.length; j++) {
        if (results[j].statusCode === 200 && results[j].json && results[j].json.status === 'ok') {
          okCount++;
        }
      }

      if (okCount !== 100) throw new Error('Expected 100 successful responses, got ' + okCount);

      return { concurrentRequests: 100, successful: okCount, durationMs: duration, avgLatencyMs: (duration / 100).toFixed(1) };
    });

    await runTest('T3.2', 'Burst concurrency on /api/servers (50 parallel requests with caching)', async function () {
      const promises = [];
      for (let i = 0; i < 50; i++) {
        promises.push(httpRequest({ hostname: '127.0.0.1', port: 8288, path: '/api/servers', method: 'GET', timeout: 8000 }));
      }
      const results = await Promise.all(promises);
      let okCount = 0;
      for (let j = 0; j < results.length; j++) {
        if (results[j].statusCode === 200 && results[j].json && Array.isArray(results[j].json.servers)) {
          okCount++;
        }
      }

      if (okCount !== 50) throw new Error('Expected 50 valid server catalog responses, got ' + okCount);

      return { total: 50, successful: okCount, serversCount: results[0].json.servers.length };
    });

    await runTest('T3.3', 'Concurrent WASM request sealing isolation (crush.wasm memory independence)', async function () {
      const wasmModule = await resolver.initWasm();
      const concurrency = 15;
      const tasks = [];

      for (let i = 0; i < concurrency; i++) {
        tasks.push(new Promise(function (resolve, reject) {
          WebAssembly.instantiate(wasmModule).then(function (instance) {
            const tmdb = 550 + i;
            const sealed = resolver.sealRequest(instance, {
              server: 'secret',
              type: 'movie',
              tmdbId: tmdb
            });

            if (!sealed.responseKey || sealed.responseKey.length !== 32) {
              return reject(new Error('Invalid responseKey length: ' + (sealed.responseKey && sealed.responseKey.length)));
            }
            if (sealed.keyId === undefined || sealed.keyId === null) {
              return reject(new Error('Missing keyId'));
            }
            if (sealed.ephemeralPublic.length !== 65) {
              return reject(new Error('Invalid ephemeralPublic length: ' + sealed.ephemeralPublic.length));
            }
            if (sealed.ciphertextBody.length <= 98) {
              return reject(new Error('Ciphertext body too small: ' + sealed.ciphertextBody.length));
            }

            resolve({ index: i, tmdb: tmdb, sealedLen: sealed.ciphertextBody.length });
          }).catch(reject);
        }));
      }

      const results = await Promise.all(tasks);
      if (results.length !== concurrency) throw new Error('Mismatch in completed tasks');

      return { concurrentWasmInstances: concurrency, completed: results.length };
    });

    await runTest('T3.4', 'Rapid request bursting (100 rapid sequential requests at 0ms delay)', async function () {
      let success = 0;
      const start = Date.now();
      for (let i = 0; i < 100; i++) {
        const res = await httpRequest({ hostname: '127.0.0.1', port: 8288, path: '/health', method: 'GET', timeout: 2000 });
        if (res.statusCode === 200) success++;
      }
      const duration = Date.now() - start;
      if (success !== 100) throw new Error('Expected 100 sequential success, got ' + success);

      return { count: 100, durationMs: duration, rateReqPerSec: ((100 / duration) * 1000).toFixed(0) };
    });

    await runTest('T3.5', 'Mixed stress workload (health + servers + stream validation + aborts)', async function () {
      const batch = [];
      // 30 health requests
      for (let h = 0; h < 30; h++) {
        batch.push(httpRequest({ hostname: '127.0.0.1', port: 8288, path: '/health', method: 'GET' }));
      }
      // 15 servers requests
      for (let s = 0; s < 15; s++) {
        batch.push(httpRequest({ hostname: '127.0.0.1', port: 8288, path: '/api/servers', method: 'GET' }));
      }
      // 10 invalid stream requests (assert proper 400 rejection under load)
      for (let st = 0; st < 10; st++) {
        batch.push(httpRequest({ hostname: '127.0.0.1', port: 8288, path: '/api/stream?tmdbId=invalid', method: 'GET' }));
      }

      const results = await Promise.all(batch);
      const health200 = results.slice(0, 30).filter(function (r) { return r.statusCode === 200; }).length;
      const servers200 = results.slice(30, 45).filter(function (r) { return r.statusCode === 200; }).length;
      const stream400 = results.slice(45, 55).filter(function (r) { return r.statusCode === 400; }).length;

      if (health200 !== 30 || servers200 !== 15 || stream400 !== 10) {
        throw new Error('Mixed workload failed expectations: health=' + health200 + '/30, servers=' + servers200 + '/15, stream400=' + stream400 + '/10');
      }

      const endHealth = await httpRequest({ hostname: '127.0.0.1', port: 8288, path: '/health', method: 'GET' });
      const rssMB = endHealth.json.memory.rss / (1024 * 1024);

      return { totalMixedRequests: 55, allMatched: true, finalRssMB: rssMB.toFixed(2) };
    });

    await runTest('T3.6', 'Input validation resilience on /api/stream and /proxy/sub', async function () {
      // 1. Missing tmdbId
      const r1 = await httpRequest({ hostname: '127.0.0.1', port: 8288, path: '/api/stream?type=movie', method: 'GET' });
      if (r1.statusCode !== 400) throw new Error('Expected 400 for missing tmdbId, got ' + r1.statusCode);

      // 2. Non-numeric tmdbId (SQL injection attempt / path traversal)
      const r2 = await httpRequest({ hostname: '127.0.0.1', port: 8288, path: '/api/stream?tmdbId=550%27OR%201=1&type=movie', method: 'GET' });
      if (r2.statusCode !== 400) throw new Error('Expected 400 for SQLi tmdbId, got ' + r2.statusCode);

      // 3. Invalid type
      const r3 = await httpRequest({ hostname: '127.0.0.1', port: 8288, path: '/api/stream?tmdbId=550&type=invalid', method: 'GET' });
      if (r3.statusCode !== 400) throw new Error('Expected 400 for invalid type, got ' + r3.statusCode);

      // 4. Missing season/episode on type=tv
      const r4 = await httpRequest({ hostname: '127.0.0.1', port: 8288, path: '/api/stream?tmdbId=1399&type=tv', method: 'GET' });
      if (r4.statusCode !== 400) throw new Error('Expected 400 for TV missing season, got ' + r4.statusCode);

      // 5. Missing url on /proxy/sub
      const r5 = await httpRequest({ hostname: '127.0.0.1', port: 8288, path: '/proxy/sub', method: 'GET' });
      if (r5.statusCode !== 400) throw new Error('Expected 400 for missing sub url, got ' + r5.statusCode);

      // 6. Missing url on /hls/proxy
      const r6 = await httpRequest({ hostname: '127.0.0.1', port: 8288, path: '/hls/proxy', method: 'GET' });
      if (r6.statusCode !== 400) throw new Error('Expected 400 for missing hls proxy url, got ' + r6.statusCode);

      // 7. Non-HTTP protocol on /hls/proxy (SSRF test)
      const r7 = await httpRequest({ hostname: '127.0.0.1', port: 8288, path: '/hls/proxy?url=file%3A%2F%2F%2Fetc%2Fpasswd', method: 'GET' });
      if (r7.statusCode !== 400) throw new Error('Expected 400 for file:// scheme, got ' + r7.statusCode);

      return { validationEndpointsChecked: 7, all400sCorrect: true };
    });

  } finally {
    await service3.kill();
    await ensurePortFree(8288, 2000);
  }

  // ===========================================================================
  // SUITE 4: Manifest Rewriting Edge Cases
  // ===========================================================================
  console.log('\n' + C.bold + '► SUITE 4: Manifest Rewriting Edge Cases' + C.reset);

  const PROXY_PREFIX = 'http://127.0.0.1:8088/hls/proxy?url=';
  const BASE_URL = 'https://cdn.lightspeed.st/stream/master.m3u8';

  await runTest('T4.1', 'Comprehensive HLS tag rewriting (#EXT-X-MEDIA, MAP, KEY, I-FRAME, PRELOAD, DATERANGE)', async function () {
    const rawManifest = [
      '#EXTM3U',
      '#EXT-X-VERSION:7',
      '#EXT-X-MEDIA:TYPE=AUDIO,GROUP-ID="audio",NAME="English",DEFAULT=YES,URI="audio/en.m3u8"',
      '#EXT-X-MEDIA:TYPE=SUBTITLES,GROUP-ID="subs",NAME="English",URI="sub/en.vtt"',
      '#EXT-X-I-FRAME-STREAM-INF:BANDWIDTH=86000,URI="iframe.m3u8"',
      '#EXT-X-KEY:METHOD=AES-128,URI="https://auth.server.com/key?id=1",IV=0x123',
      '#EXT-X-MAP:URI="init.mp4",BYTERANGE="718@0"',
      '#EXT-X-PRELOAD-HINT:TYPE=PART,URI="part1.m4s"',
      '#EXT-X-DATERANGE:ID="ad-1",X-ASSET-URI="ad.m3u8"',
      '#EXT-X-STREAM-INF:BANDWIDTH=2560000,RESOLUTION=1920x1080',
      '1080p/index.m3u8'
    ].join('\n');

    const rewritten = hlsProxy.rewriteManifest(rawManifest, BASE_URL, PROXY_PREFIX);

    // Verify all URI tags are rewritten with PROXY_PREFIX
    const expectedSubstrings = [
      'URI="' + PROXY_PREFIX + encodeURIComponent('https://cdn.lightspeed.st/stream/audio/en.m3u8') + '"',
      'URI="' + PROXY_PREFIX + encodeURIComponent('https://cdn.lightspeed.st/stream/sub/en.vtt') + '"',
      'URI="' + PROXY_PREFIX + encodeURIComponent('https://cdn.lightspeed.st/stream/iframe.m3u8') + '"',
      'URI="' + PROXY_PREFIX + encodeURIComponent('https://auth.server.com/key?id=1') + '"',
      'URI="' + PROXY_PREFIX + encodeURIComponent('https://cdn.lightspeed.st/stream/init.mp4') + '"',
      'URI="' + PROXY_PREFIX + encodeURIComponent('https://cdn.lightspeed.st/stream/part1.m4s') + '"',
      'X-ASSET-URI="' + PROXY_PREFIX + encodeURIComponent('https://cdn.lightspeed.st/stream/ad.m3u8') + '"',
      PROXY_PREFIX + encodeURIComponent('https://cdn.lightspeed.st/stream/1080p/index.m3u8')
    ];

    for (let i = 0; i < expectedSubstrings.length; i++) {
      if (!rewritten.includes(expectedSubstrings[i])) {
        throw new Error('Missing expected rewritten tag: ' + expectedSubstrings[i] + '\nManifest:\n' + rewritten);
      }
    }

    return { allTagsRewritten: true, tagsVerified: expectedSubstrings.length };
  });

  await runTest('T4.2', 'Manifest rewriting idempotency (no double-wrapping on re-rewrite)', async function () {
    const rawManifest = [
      '#EXTM3U',
      '#EXT-X-MAP:URI="init.mp4"',
      'segment1.m4s'
    ].join('\n');

    const pass1 = hlsProxy.rewriteManifest(rawManifest, BASE_URL, PROXY_PREFIX);
    const pass2 = hlsProxy.rewriteManifest(pass1, BASE_URL, PROXY_PREFIX);

    if (pass1 !== pass2) {
      throw new Error('Manifest rewriting is not idempotent!\nPass 1:\n' + pass1 + '\nPass 2:\n' + pass2);
    }

    if (pass2.includes('url=http%3A%2F%2F127.0.0.1%3A8088%2Fhls%2Fproxy')) {
      throw new Error('Double proxy wrapping detected in pass 2');
    }

    return { idempotent: true, doubleWrappingPrevented: true };
  });

  await runTest('T4.3', 'Relative path resolution variations (relative, root-relative, parent-relative, protocol-relative)', async function () {
    const rawManifest = [
      '#EXTM3U',
      '# 1. Standard relative',
      'segment001.ts',
      '# 2. Root-relative',
      '/hls/global/segment002.ts',
      '# 3. Parent-relative (dot segments)',
      '../other/segment003.ts',
      '# 4. Protocol-relative',
      '//othercdn.com/stream/segment004.ts',
      '# 5. Fully qualified absolute with port',
      'https://secure.cdn.com:8443/seg005.ts'
    ].join('\n');

    const rewritten = hlsProxy.rewriteManifest(rawManifest, 'https://cdn.lightspeed.st/v1/sub/master.m3u8', PROXY_PREFIX);

    const expectedUrls = [
      PROXY_PREFIX + encodeURIComponent('https://cdn.lightspeed.st/v1/sub/segment001.ts'),
      PROXY_PREFIX + encodeURIComponent('https://cdn.lightspeed.st/hls/global/segment002.ts'),
      PROXY_PREFIX + encodeURIComponent('https://cdn.lightspeed.st/v1/other/segment003.ts'),
      PROXY_PREFIX + encodeURIComponent('https://othercdn.com/stream/segment004.ts'),
      PROXY_PREFIX + encodeURIComponent('https://secure.cdn.com:8443/seg005.ts')
    ];

    for (let i = 0; i < expectedUrls.length; i++) {
      if (!rewritten.includes(expectedUrls[i])) {
        throw new Error('Path resolution failed for URL: ' + expectedUrls[i] + '\nManifest:\n' + rewritten);
      }
    }

    return { allPathVariantsResolved: true, verifiedCount: expectedUrls.length };
  });

  await runTest('T4.4', 'Query parameters, url-escaped tokens, and fragments in segments', async function () {
    const rawManifest = [
      '#EXTM3U',
      '#EXTINF:6.0,',
      'seg1.mp4?token=abc%20123&exp=1700000000&signature=xyz%3D%3D#frag1'
    ].join('\n');

    const rewritten = hlsProxy.rewriteManifest(rawManifest, BASE_URL, PROXY_PREFIX);

    const expectedTarget = 'https://cdn.lightspeed.st/stream/seg1.mp4?token=abc%20123&exp=1700000000&signature=xyz%3D%3D#frag1';
    const expectedLine = PROXY_PREFIX + encodeURIComponent(expectedTarget);

    if (!rewritten.includes(expectedLine)) {
      throw new Error('Query parameter / token encoding failed!\nExpected: ' + expectedLine + '\nGot:\n' + rewritten);
    }

    return { queryParamsPreserved: true, tokensIntact: true };
  });

  await runTest('T4.5', 'Malformed manifests: UTF-8 BOM, mixed CRLF/LF line endings, whitespace tolerance', async function () {
    // Manifest with BOM, mixed CRLF, whitespace padding, non-URI comments
    const rawManifest = '\uFEFF#EXTM3U\r\n' +
      '#EXT-X-VERSION:3\r\n' +
      '# Custom comment line\n' +
      '#EXT-X-TARGETDURATION:10\r\n' +
      '#EXTINF:9.009,\r\n' +
      '   segment_whitespace.ts   \r\n' +
      '#EXT-X-DISCONTINUITY\n' +
      '\r\n' + // Blank line
      '#EXTINF:9.009,\n' +
      'segment_after_blank.ts\n';

    const rewritten = hlsProxy.rewriteManifest(rawManifest, BASE_URL, PROXY_PREFIX);

    if (!rewritten.includes(PROXY_PREFIX + encodeURIComponent('https://cdn.lightspeed.st/stream/segment_whitespace.ts'))) {
      throw new Error('Whitespace-padded segment was not rewritten correctly:\n' + rewritten);
    }
    if (!rewritten.includes(PROXY_PREFIX + encodeURIComponent('https://cdn.lightspeed.st/stream/segment_after_blank.ts'))) {
      throw new Error('Segment after blank line was not rewritten correctly:\n' + rewritten);
    }
    if (!rewritten.includes('#EXT-X-DISCONTINUITY')) {
      throw new Error('#EXT-X-DISCONTINUITY tag was lost');
    }

    return { bomHandled: true, mixedEndingsHandled: true, whitespaceTolerated: true };
  });

  await runTest('T4.6', 'Extreme scale manifest performance stress (25,000 lines synthetic VOD)', async function () {
    // Generate 25,000 lines (simulating ~14-hour continuous stream)
    const lines = ['#EXTM3U', '#EXT-X-VERSION:4', '#EXT-X-TARGETDURATION:2', '#EXT-X-MEDIA-SEQUENCE:0'];
    for (let i = 0; i < 12498; i++) {
      lines.push('#EXTINF:2.000,');
      lines.push('seg_' + i + '.m4s');
    }
    lines.push('#EXT-X-ENDLIST');
    const largeManifest = lines.join('\n');

    const startMem = process.memoryUsage().heapUsed;
    const startTime = Date.now();
    const rewritten = hlsProxy.rewriteManifest(largeManifest, BASE_URL, PROXY_PREFIX);
    const duration = Date.now() - startTime;
    const endMem = process.memoryUsage().heapUsed;
    const heapDiffMB = (endMem - startMem) / (1024 * 1024);

    if (duration > 150) {
      throw new Error('Manifest rewriting too slow: ' + duration + 'ms (threshold: 150ms)');
    }

    if (!rewritten.includes('seg_0.m4s') || !rewritten.includes('seg_12497.m4s')) {
      throw new Error('Large manifest incomplete after rewrite');
    }

    return { totalLines: lines.length, segments: 12498, durationMs: duration, heapDiffMB: heapDiffMB.toFixed(2) };
  });

  // ===========================================================================
  // SUMMARY AND VERDICT
  // ===========================================================================
  console.log('\n' + C.bold + '================================================================' + C.reset);
  console.log(C.bold + '► Adversarial Stress Verification Summary' + C.reset);
  console.log('----------------------------------------------------------------');
  console.log('  Total Tests Executed: ' + testCount);
  console.log('  Passed:               ' + C.green + passCount + C.reset);
  console.log('  Failed:               ' + (failCount > 0 ? C.red + failCount + C.reset : '0'));
  console.log('----------------------------------------------------------------');

  const allPassed = failCount === 0;
  if (allPassed) {
    console.log(C.bold + C.green + 'VERDICT: ALL ' + testCount + ' ADVERSARIAL STRESS TESTS PASSED (100% SUCCESS)' + C.reset);
  } else {
    console.log(C.bold + C.red + 'VERDICT: ' + failCount + ' TESTS FAILED' + C.reset);
  }
  console.log('================================================================\n');

  // Export JSON results for reporting
  const reportPath = path.resolve(__dirname, 'adversarial-results.json');
  fs.writeFileSync(reportPath, JSON.stringify({
    timestamp: new Date().toISOString(),
    total: testCount,
    passed: passCount,
    failed: failCount,
    allPassed: allPassed,
    results: testResults
  }, null, 2), 'utf8');

  process.exit(allPassed ? 0 : 1);
}

runAllSuites().catch(function (err) {
  console.error('\n' + C.red + 'Fatal suite runner exception:' + C.reset, err);
  process.exit(1);
});

